void reset_net(void)
{
    settingsnet_state_param_t net_state;
    s32             ret;

    net_state.network_state = 0;
    net_state.sim       = 0;
    ret                 = aic_md_write(MD_ID_SETTING_NET,sizeof(settingsnet_state_param_t),&net_state);

    if (ret) {
        APP_LOGI("reset_net read net cfg error 0x%x\n",ret);
        }
}

uint8_t is_set_net_flight_flash(void)
{
    settingsnet_state_param_t net_state;
    s32             ret;

    ret                 = aic_md_read(MD_ID_SETTING_NET,sizeof(settingsnet_state_param_t),&net_state);

    if (ret) {
        APP_LOGI("read net cfg error 0x%x\n",ret);
        net_state.network_state = 0;
        }

    return net_state.network_state;
}

uint8_t get_enabled_sim_slot(void)
{
    settingsnet_state_param_t net_state;
    s32             ret;

    APP_LOGI("get_enabled_sim_slot 0\n");

    ret                 = aic_md_read(MD_ID_SETTING_NET,sizeof(settingsnet_state_param_t),&net_state);

    if (ret) {
        APP_LOGI("reset_net read net cfg error 0x%x\n",ret);
        }

    if (net_state.sim >= 2)
        net_state.sim = 0;

    APP_LOGI("get_enabled_sim_slot 1\n");
    return net_state.sim;
}


