static int32_t fligtmode_update_result(int32_t res)
{
    if (0 == res) {
        s32             ret;
        uint8_t         status = 0;
        settingsnet_state_param_t net_state;

        ret                 = aic_md_read(MD_ID_SETTING_NET,sizeof(settingsnet_state_param_t),&net_state);

        if (ret) {
            APP_LOGI("read net cfg error 0x%x\n",ret);
            net_state.network_state = 0;
            }

        status              = settings_fp_flow_get_flightmode_status();
        net_state.network_state = status;
        ret                 = aic_md_write(MD_ID_SETTING_NET,sizeof(settingsnet_state_param_t),&net_state);
        APP_LOGI("set flightmode success!");

        if (status) {
            uint8_t         index = 3;

            alv_am_win_jump_action(NULL,"set_flight_result",(void *) &index);
            }
        else {
            uint8_t         index = 4;

            alv_am_win_jump_action(NULL,"set_flight_result",(void *) &index);
            }

        //TODO: phone_fresh_selectsim ？
        }
    else {
        /* set flightmode failed, revert UI*/
        uint8_t         index = 2;

        alv_am_win_jump_action(NULL,"set_flight_result",(void *) &index);
        APP_LOGI("set flightmode failed!");
        }

    return 0;
}


void fligtmode_start_change(uint8_t on_off)
{
    // Your code here
    int32_t         ret = 0;
    uint8_t         card_id = 0;

    card_id             = settings_flow_get_current_cardid();
    ret                 = settings_flow_flightmode(card_id,on_off,fligtmode_update_result);
    APP_LOGI("set flightmode status(%d), return %ld",on_off,ret);
}


