static int32_t selectsim_update_result(int32_t res)
{
    if (0 == res) {
        LV_LOG_INFO("selectsim success!");
        uint8_t         card_id = settings_flow_get_current_cardid();
        s32             ret;
        settingsnet_state_param_t net_state;

        ret                 = aic_md_read(MD_ID_SETTING_NET,sizeof(settingsnet_state_param_t),&net_state);

        if (ret) {
            APP_LOGI("read net cfg error 0x%x\n",ret);
            net_state.network_state = 0;
            }

        net_state.sim       = card_id;
        ret                 = aic_md_write(MD_ID_SETTING_NET,sizeof(settingsnet_state_param_t),&net_state);

        if (card_id) {
            uint8_t         index = 4;

            alv_am_win_jump_action(NULL,"set_sim_switch",(void *) &index);
            }
        else {
            uint8_t         index = 3;

            alv_am_win_jump_action(NULL,"set_sim_switch",(void *) &index);
            }

        tele_phonebook_reset_init_steps();
        }
    else {

        uint8_t         index = 2;

        alv_am_win_jump_action(NULL,"set_sim_switch",(void *) &index);
        }

    return 0;
}


void simswitch_start_change(int32_t card_id)
{
    int32_t         ret = 0;

    ret                 = settings_flow_dual_sim_select_card((uint8_t) card_id,selectsim_update_result);
}


