/////////////////////////////////////////////////////////////////////////////////
static uint32_t get_setting_net_sim_childId(uint32_t child_cnt)
{
    /*Modify manually*/
    lv_obj_t *      ui_setting_child = NULL;
    uint32_t        child_id;

    for (child_id = 0; child_id < child_cnt; child_id++) {
        ui_setting_child    = lv_obj_get_child(ui_FpSettingsNetSimIndex,child_id);

        if (lv_obj_has_state(ui_setting_child,LV_STATE_FOCUSED)) {
            break;
            }

        }

    if (child_id >= child_cnt) {
        child_id            = 0;
        }

    //__inf("get_setting_childId:%d,child_cnt:%d\r\n",child_id,child_cnt);
    return child_id;
}


void settings_net_app_sim_ui_event_actions(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    //lv_obj_t * target = lv_event_get_target(e);
    uint32_t        child_cnt = lv_obj_get_child_cnt(ui_FpSettingsNetSimIndex);
    uint32_t        child_id = get_setting_net_sim_childId(child_cnt);
    lv_obj_t *      get_focus_obj = NULL;
    lv_obj_t *      pre_focus_obj = NULL;

    __inf("settings_net_app_lock_ui_event_actions 00 =%d\r\n",event_code);


    switch (event_code)
    {
        case LV_EVENT_SCREEN_LOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_add_obj(lv_group_get_default(),obj);
                    lv_group_focus_obj(obj);
                    }

                }
            break;

        case LV_EVENT_SCREEN_UNLOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_remove_obj(obj);
                    }
                }
            break;

        case LV_EVENT_KEY:
            {
                uint32_t        key = lv_event_get_key(e);

                __inf("settings_net_app_lock_ui_event_actions111 LV_EVENT_KEY:%d\r\n",key);

                if (key == LV_KEY_UP) {
                    //__inf("LV_KEY_UP,child_id:%d,child_cnt:%d\r\n",child_id,child_cnt);
                    if (child_id != 0) {
                        pre_focus_obj       = lv_obj_get_child(ui_FpSettingsNetSimIndex,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        lv_label_set_long_mode(pre_focus_obj,LV_LABEL_LONG_CLIP);


                        get_focus_obj       = lv_obj_get_child(ui_FpSettingsNetSimIndex,child_id - 1);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(get_focus_obj,PHONEBOOK_NAME_TEXT_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(get_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        if ((child_id - 1) == 0) {
                            lv_obj_scroll_to_y(ui_FpSettingsNetSimIndex,0,LV_ANIM_OFF);

                            }
                        else {
                            lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);

                            }

                        lv_label_set_long_mode(get_focus_obj,LV_LABEL_LONG_SCROLL_CIRCULAR);

                        }
                    else {
                        pre_focus_obj       = lv_obj_get_child(ui_FpSettingsNetSimIndex,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_label_set_long_mode(pre_focus_obj,LV_LABEL_LONG_CLIP);

                        get_focus_obj       = lv_obj_get_child(ui_FpSettingsNetSimIndex,child_cnt - 1);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(get_focus_obj,PHONEBOOK_NAME_TEXT_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(get_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        //__inf("get_focus_obj :%d\r\n",lv_obj_has_state(get_focus_obj, LV_STATE_FOCUSED));
                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                        lv_label_set_long_mode(get_focus_obj,LV_LABEL_LONG_SCROLL_CIRCULAR);

                        }

                    app_fp_play_tts_menu(lv_label_get_text(get_focus_obj));
                    }
                else if (key == LV_KEY_DOWN) {

                    if (child_id != child_cnt - 1) {
                        pre_focus_obj       = lv_obj_get_child(ui_FpSettingsNetSimIndex,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_label_set_long_mode(pre_focus_obj,LV_LABEL_LONG_CLIP);

                        get_focus_obj       = lv_obj_get_child(ui_FpSettingsNetSimIndex,child_id + 1);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(get_focus_obj,PHONEBOOK_NAME_TEXT_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(get_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                        lv_label_set_long_mode(get_focus_obj,LV_LABEL_LONG_SCROLL_CIRCULAR);

                        }
                    else {
                        pre_focus_obj       = lv_obj_get_child(ui_FpSettingsNetSimIndex,child_id);
                        lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(pre_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_label_set_long_mode(pre_focus_obj,LV_LABEL_LONG_CLIP);

                        get_focus_obj       = lv_obj_get_child(ui_FpSettingsNetSimIndex,0);
                        lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);
                        lv_obj_set_style_text_color(get_focus_obj,PHONEBOOK_NAME_TEXT_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_bg_color(get_focus_obj,PHONEBOOK_NAME_TEXT_BG_COLOR_FOCUS,
                            LV_PART_MAIN | LV_STATE_DEFAULT);

                        lv_obj_scroll_to_y(ui_FpSettingsNetSimIndex,0,LV_ANIM_OFF);
                        lv_label_set_long_mode(get_focus_obj,LV_LABEL_LONG_SCROLL_CIRCULAR);

                        }

                    app_fp_play_tts_menu(lv_label_get_text(get_focus_obj));
                    }
                else if (key == LV_KEY_LEFT) {

                    }
                else if (key == LV_KEY_DEL) {
                    uint8_t         index = 1;

                    alv_am_win_jump_action(NULL,"settings_net",(void *) &index);
                    }
                else if ((key == LV_KEY_ESC) || (key == LV_KEY_ENTER)) {
                    settingsnet_state_param_t net_state;
                    s32             ret;

                    ret                 = aic_md_read(MD_ID_SETTING_NET,sizeof(settingsnet_state_param_t),&net_state);

                    if (ret) {
                        APP_LOGI("reset_net read net cfg error 0x%x\n",ret);
                        }

                    uint32_t        sim_status = 0xff;
                    uint8_t         cur_card_id = 2;

                    sim_status          = network_get_sim_status(&cur_card_id);

                    if (cur_card_id >= 2) {
                        uint8_t         index = 6;

                        alv_am_win_jump_action(NULL,"set_sim_switch",(void *) &index);
                        return;
                        }

                    if (cur_card_id == child_id) {
                        uint8_t         index = 0;

                        if (child_id)
                            index = 1;
                        else 
                            index = 0;

                        alv_am_win_jump_action(NULL,"set_sim_switch",(void *) &index);
                        }
                    else {
                        extern uint32_t phonebook_data_is_init();

                        if (phonebook_data_is_init()) // 读取电话本时不允许切换SIM卡
                        {
                            simswitch_start_change(child_id); // 切卡
                            alv_am_win_jump_action(NULL,"set_sim_switch",NULL);
                            }
                        else {
                            uint8_t         index = 5;

                            alv_am_win_jump_action(NULL,"set_sim_switch",(void *) &index);
                            }

                        }

                    }
                else if (key == LV_KEY_END)
                    alv_am_app_exit_action_all();

                }
            break;

        default:
            break;
        }


}


